function ConvertTo(n){var u=$("#SourceDataID").val(),i=$("#gridDXF").data("kendoGrid"),t=[],r=0;i.select().each(function(){var n=i.dataItem($(this));t[r]=n.SourceDataID;++r});t.length>0&&$.ajax({type:"POST",url:"/CadImport/ConvertTo",dataType:"json",data:{IDList:t,Units:n},success:function(n){}})}
function UpdateDXF_LoadNew(n){var t=$("#DXFEditID").val(),i=GetUpdateList(WebGLCADDisp.dataGroup);typeof n!="undefined"&&$.ajax({type:"POST",url:"/CadImport/UpdateDataNext",dataType:"json",data:{ItemList:i,SourceID:t,ReturnItemID:n},success:function(i){}})}
function DoCreateDXFParts(n,t){var e=$("#img").height(),o=$("#img").width(),r=[],u=$("#gridOther").data("kendoGrid").dataSource.data();for(var i=0;i<u.length;i++)r.push(u[i].FileID);var f=$("#InventoryLocation").val();$.ajax({type:"POST",url:"/part/create",dataType:"json",data:{Location:f,IDList:n,unitList:t,OtherFileIDList:r,Height:e,Width:o},success:function(t){var i=$("#gridDXFParts").data("kendoGrid");for(var e=0;e<t.List.length;e++)i.dataSource.data().toJSON().push(t.List[e])}})}
function createAllParts(){var t=$("#gridDXF").data("kendoGrid"),r=[],u=[];if(t){var i=t.dataSource.data();for(var n=0;n<i.length;n++)r.push(i[n].SourceDataID),u.push(i[n].Units);DoCreateDXFParts(r,u)}$('#ulDXFTab a[href="#dxfparts"]').tab("show")}
